import {EXHIBITION_FARMS,EXHIBITION_STEPS,exhibitionFarm} from './exhibition-data.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function exhibitionHTML(state){
  const active=exhibitionFarm(state.exhibition?.farmId);
  return `<div class="page-heading"><div><div class="eyebrow">READY FOR THE EXHIBITION</div><h1>Three farms. Three possible futures.</h1><p>Choose a story and walk through one connected farm, from past harvests to future decisions.</p></div><button class="btn secondary" data-exhibit-download>Download dataset</button></div>
  <section class="exhibit-intro"><div><span class="eyebrow light">THE FARM TIME MACHINE · DEMO COLLECTION</span><h2>A story behind every number.</h2><p>30 past seasons. 18 linked harvest outcomes. Three soil types, water budgets, and climate challenges.</p></div><div class="exhibit-duration"><strong>2:40</strong><span>suggested walkthrough</span></div></section>
  <div class="exhibit-farms">${EXHIBITION_FARMS.map(p=>`<article class="exhibit-farm ${p.id===active?.id?'is-active':''}" style="--story-color:${p.color}"><div class="exhibit-card-top"><span>${esc(p.region)} · ${p.state.farm.area} ha</span><span>${p.id===active?.id?'LOADED':'FICTIONAL FARM'}</span></div><h2>${esc(p.name)}</h2><span class="exhibit-tag">${esc(p.tag)}</span><h3>${esc(p.headline)}</h3><p>${esc(p.summary)}</p><dl><div><dt>Soil & cover</dt><dd>${esc(p.state.farm.soil)} · ${esc(p.state.farm.residue)}</dd></div><div><dt>Annual irrigation</dt><dd>${p.state.farm.water} mm</dd></div><div><dt>Stress test</dt><dd>${p.scenario.year} · ${p.scenario.type}</dd></div><div><dt>Comparisons</dt><dd>Adaptive + 2 crop sequences</dd></div></dl><button class="btn ${p.id===active?.id?'secondary':''}" data-load-exhibition="${p.id}">${p.id===active?.id?'Reset & restart this story':'Load '+esc(p.region)+' story'} <span aria-hidden="true">→</span></button></article>`).join('')}</div>
  <section class="panel padded"><div class="section-title"><div><h2>Your recording route</h2><p>${active?esc(active.name)+' is loaded. Jump to any scene, or use Next scene.':'Load a farm to begin. Each scene sets up the relevant screen and scenario.'}</p></div>${active?'<button class="btn secondary" data-exhibit-scene="0">Start walkthrough</button>':''}</div><div class="exhibit-scenes">${EXHIBITION_STEPS.map((s,i)=>`<button data-exhibit-scene="${i}" ${active?'':'disabled'} ${active&&state.exhibition.step===i?'aria-current="step"':''}><span>${String(i+1).padStart(2,'0')}</span><strong>${s.title}</strong><small>${s.seconds}s${s.stress?' · stress active':''}</small></button>`).join('')}</div></section>
  <div class="exhibit-foot"><p><b>Illustrative exhibition data.</b> Farm names, field outlines, histories, climate values, and outcomes are synthetic examples. Future results are calculated by TerraLoop’s prototype model. They are not NASA observations or forecasts.</p><p>Loading a story keeps a backup of your current farm in this browser. Switching or restarting stories preserves that backup.</p>${active?'<button class="btn secondary" data-exhibit-restore>Restore my previous farm</button>':''}</div>`;
}
export function exhibitionChrome(state,page){
  const p=exhibitionFarm(state.exhibition?.farmId);if(!p||page==='exhibition')return '';
  const i=Math.max(0,Math.min(EXHIBITION_STEPS.length-1,state.exhibition.step||0));
  const open=state.exhibition.guide!==false;
  return `<section class="exhibit-bar" aria-label="Exhibition walkthrough"><div class="exhibit-status"><span class="exhibit-dot"></span><b>${esc(p.name)}</b><span>Synthetic demo</span></div><div class="exhibit-controls"><button class="text-button" data-exhibit-studio>Stories</button><button class="text-button" data-exhibit-toggle>${open?'Hide guide':'Show guide'}</button>${open?`<label class="exhibit-select-label"><span class="sr-only">Recording scene</span><select id="exhibit-scene-select" aria-label="Recording scene">${EXHIBITION_STEPS.map((s,n)=>`<option value="${n}" ${n===i?'selected':''}>${n+1} / 10 · ${s.title}</option>`).join('')}</select></label><button class="btn secondary exhibit-back" data-exhibit-scene="${i-1}" ${i===0?'disabled':''} aria-label="Previous scene">←</button><button class="btn" data-exhibit-scene="${i===9?0:i+1}">${i===9?'Restart tour':'Next scene'} <span aria-hidden="true">→</span></button>`:''}</div></section>${open?`<div class="exhibit-cue"><span class="eyebrow">THE FARM STORY</span><p>${esc(p.cues[page]||p.summary)}</p></div>`:''}`;
}
export function bindExhibitionControls({load,scene,restore,download,studio,toggle}){
  document.querySelectorAll('[data-load-exhibition]').forEach(el=>el.onclick=()=>load(el.dataset.loadExhibition));
  document.querySelectorAll('[data-exhibit-scene]').forEach(el=>el.onclick=()=>scene(+el.dataset.exhibitScene));
  document.querySelector('[data-exhibit-restore]')?.addEventListener('click',restore);
  document.querySelector('[data-exhibit-download]')?.addEventListener('click',download);
  document.querySelector('[data-exhibit-studio]')?.addEventListener('click',studio);
  document.querySelector('[data-exhibit-toggle]')?.addEventListener('click',toggle);
  document.querySelector('#exhibit-scene-select')?.addEventListener('change',e=>scene(+e.target.value));
}
